def parser(log: str) -> dict[str, str]:
    import re

    results: dict[str, str] = {}
    ansi_escape = re.compile(r"\x1b\[[0-?]*[ -/]*[@-~]")
    test_line = re.compile(
        r"^\s*(PASS|FAIL|SKIP|ERROR|XFAIL|XPASS)\s*:\s*(\S(?:.*\S)?)\s*$",
        re.IGNORECASE,
    )
    status_map = {
        "PASS": "pass",
        "SKIP": "skip",
        "FAIL": "fail",
        "ERROR": "fail",
        "XFAIL": "fail",
        "XPASS": "fail",
    }
    priority = {"pass": 0, "skip": 1, "fail": 2}

    for raw_line in log.splitlines():
        line = ansi_escape.sub("", raw_line).rstrip("\r")
        match = test_line.match(line)
        if not match:
            continue

        outcome, test_name = match.groups()
        status = status_map[outcome.upper()]
        test_name = test_name.strip()

        previous = results.get(test_name)
        if previous is None or priority[status] > priority[previous]:
            results[test_name] = status

    return results

