        if (
            case.get("skipped") is True
            or case.get("pending") is True
            or case.get("todo") is True
            or case.get("disabled") is True
            or status in {
                "skip", "skipped", "pending", "todo", "disabled",
                "xit", "xtest", "not run", "notrun",
            }
        ):
            return "skip"

        # Explicit errors/failures take precedence over a contradictory status.
        for field in ("failureMessages", "failureDetails", "errors"):
            value = case.get(field)
            if isinstance(value, (list, tuple, dict)) and len(value) > 0:
                return "fail"
            if isinstance(value, str) and value.strip():
                return "fail"

        if case.get("error") not in (None, False, "", [], {}):
            return "fail"
        if case.get("failure") not in (None, False, "", [], {}):
            return "fail"

        if status in {"pass", "passed", "success", "successful", "ok"}:
            return "pass"

        # Any failure, error, unknown, or incomplete state is a failure.
        return "fail"

    def case_name(case: dict) -> str:
        full = case.get("fullName")
        if full is None:
            full = case.get("full_name")
        if full is not None and str(full).strip():
            return str(full).strip()

        title = case.get("title")
        if title is None:
            title = case.get("name")
        title_text = str(title or "<unnamed>").strip() or "<unnamed>"

        ancestors = case.get("ancestorTitles")
        if ancestors is None:
            ancestors = case.get("ancestors")
        if isinstance(ancestors, list):
            parts = [str(item).strip() for item in ancestors if str(item).strip()]
            if parts:
                return " ".join(parts + [title_text])
        return title_text

    def parse_report(obj: object) -> int:
        before = len(results)

        if isinstance(obj, list):
            # A top-level list may contain one or more complete reports.
            for item in obj:
                if isinstance(item, dict) and any(
