        re.compile(
            r"^\s*---\s+(?P<status>PASS|FAIL|SKIP):\s+(?P<name>.+?)(?:\s+\(\S+\))?\s*$",
            re.IGNORECASE,
        ),
        # Vitest/Jest symbols.
        re.compile(
            r"^\s*(?P<status>[✓✔√✕✖×○◯])\s+(?P<name>.+?)(?:\s+\d+(?:\.\d+)?\s*m?s)?\s*$"
        ),
    ]

    for line in clean.splitlines():
        for pattern in patterns:
            match = pattern.match(line)
            if not match:
                continue

            raw = match.group("status").lower()
            if raw in {"pass", "passed", "ok", "✓", "✔", "√"}:
                status = "pass"
            elif raw in {"skip", "skipped", "xfail", "○", "◯"}:
                status = "skip"
            else:
                status = "fail"

            add(match.group("name").strip(), status)
