def parser(log: str) -> dict[str, str]:
    import json
    import re

    results: dict[str, str] = {}

    def add(name: object, status: str) -> None:
        key = str(name).strip() or "<unnamed>"
        if key not in results:
            results[key] = status
            return

        # Preserve repeated tests rather than silently overwriting them.
        if results[key] == status:
            base = key
        else:
            base = key
        number = 2
        while f"{base} [{number}]" in results:
            number += 1
        results[f"{base} [{number}]"] = status

    def normalize_file(value: object) -> str:
        path = str(value or "").replace("\\", "/")
        path = re.sub(r"/+", "/", path)

        # Keep stable project-relative test paths where possible.
        match = re.search(r"(?:^|/)(__tests__/.*)$", path)
        if match:
            return match.group(1)

        return path.removeprefix("./")

    def case_status(case: dict) -> str:
        raw = case.get("status")
        if raw is None:
            raw = case.get("state")
        if raw is None:
            raw = case.get("result")

        status = str(raw or "").strip().lower().replace("_", " ").replace("-", " ")

        if (
            case.get("skipped") is True
            or case.get("pending") is True
            or case.get("todo") is True
            or case.get("disabled") is True
            or status in {
                "skip", "skipped", "pending", "todo", "disabled",
                "xit", "xtest", "not run", "notrun",
            }
        ):
            return "skip"

        # Explicit errors/failures take precedence over a contradictory status.
        for field in ("failureMessages", "failureDetails", "errors"):
            value = case.get(field)
            if isinstance(value, (list, tuple, dict)) and len(value) > 0:
                return "fail"
            if isinstance(value, str) and value.strip():
                return "fail"

        if case.get("error") not in (None, False, "", [], {}):
            return "fail"
        if case.get("failure") not in (None, False, "", [], {}):
            return "fail"

        if status in {"pass", "passed", "success", "successful", "ok"}:
            return "pass"

        # Any failure, error, unknown, or incomplete state is a failure.
        return "fail"

    def case_name(case: dict) -> str:
        full = case.get("fullName")
        if full is None:
            full = case.get("full_name")
        if full is not None and str(full).strip():
            return str(full).strip()

        title = case.get("title")
        if title is None:
            title = case.get("name")
        title_text = str(title or "<unnamed>").strip() or "<unnamed>"

        ancestors = case.get("ancestorTitles")
        if ancestors is None:
            ancestors = case.get("ancestors")
        if isinstance(ancestors, list):
            parts = [str(item).strip() for item in ancestors if str(item).strip()]
            if parts:
                return " ".join(parts + [title_text])
        return title_text

    def parse_report(obj: object) -> int:
        before = len(results)

        if isinstance(obj, list):
            # A top-level list may contain one or more complete reports.
            for item in obj:
                if isinstance(item, dict) and any(
                    key in item for key in ("testResults", "test_results", "numTotalTests")
                ):
                    parse_report(item)
            return len(results) - before

        if not isinstance(obj, dict):
            return 0

        suites = obj.get("testResults")
        if suites is None:
            suites = obj.get("test_results")

        # Some compatible reporters call the suite collection "results".
        if suites is None:
            candidate = obj.get("results")
            if isinstance(candidate, list) and any(
                isinstance(item, dict)
                and any(key in item for key in ("assertionResults", "assertions", "tests"))
                for item in candidate
            ):
                suites = candidate

        if not isinstance(suites, list):
            return 0

        for suite in suites:
            if not isinstance(suite, dict):
                continue

            filename = normalize_file(
                suite.get("name")
                or suite.get("testFilePath")
                or suite.get("file")
                or suite.get("filepath")
                or ""
            )

            cases = suite.get("assertionResults")
            if cases is None:
                cases = suite.get("assertions")
            if cases is None:
                cases = suite.get("tests")
            if not isinstance(cases, list):
                continue

            for case in cases:
                if not isinstance(case, dict):
                    continue
                name = case_name(case)
                key = f"{filename}::{name}" if filename else name
                add(key, case_status(case))

        return len(results) - before

    # Fast path for a clean JSON document.
    text = log.lstrip("\ufeff \t\r\n")
    try:
        parse_report(json.loads(text))
    except (json.JSONDecodeError, TypeError, ValueError):
        pass

    # Reporter output may be surrounded by console noise. Decode each complete
    # JSON value without depending on property order or an exact prefix.
    if not results:
        decoder = json.JSONDecoder()
        position = 0
        while position < len(log):
            object_start = log.find("{", position)
            array_start = log.find("[", position)
            starts = [item for item in (object_start, array_start) if item >= 0]
            if not starts:
                break
            start = min(starts)

            try:
                value, consumed = decoder.raw_decode(log[start:])
            except (json.JSONDecodeError, TypeError, ValueError):
                position = start + 1
                continue

            parse_report(value)
            position = start + max(consumed, 1)

    if results:
        return results

    # Last-resort fallback for ordinary textual test output. This is deliberately
    # used only when no granular JSON assertions were available.
    ansi = re.compile(r"\x1b\[[0-?]*[ -/]*[@-~]")
    clean = ansi.sub("", log)

    patterns = [
        # pytest and node test identifiers:
        # file.py::Class::test_name PASSED
        re.compile(
            r"^\s*(?P<name>\S.*?::\S.*?)\s+"
            r"(?P<status>PASSED|FAILED|SKIPPED|ERROR|XFAIL|XPASS)\b",
            re.IGNORECASE,
        ),
        # unittest:
        # test_method (module.Class) ... ok
        re.compile(
            r"^\s*(?P<name>\S.*?)(?:\s+\.\.\.\s+)"
            r"(?P<status>ok|FAIL|ERROR|skipped)(?:\b|$)",
            re.IGNORECASE,
        ),
        # Go:
        # --- PASS: TestName
        re.compile(
            r"^\s*---\s+(?P<status>PASS|FAIL|SKIP):\s+(?P<name>.+?)(?:\s+\(\S+\))?\s*$",
            re.IGNORECASE,
        ),
        # Vitest/Jest symbols.
        re.compile(
            r"^\s*(?P<status>[✓✔√✕✖×○◯])\s+(?P<name>.+?)(?:\s+\d+(?:\.\d+)?\s*m?s)?\s*$"
        ),
    ]

    for line in clean.splitlines():
        for pattern in patterns:
            match = pattern.match(line)
            if not match:
                continue

            raw = match.group("status").lower()
            if raw in {"pass", "passed", "ok", "✓", "✔", "√"}:
                status = "pass"
            elif raw in {"skip", "skipped", "xfail", "○", "◯"}:
                status = "skip"
            else:
                status = "fail"

            add(match.group("name").strip(), status)
            break

    return results

