def parser(log: str) -> dict[str, str]:
    import re
    import xml.etree.ElementTree as ET

    results: dict[str, str] = {}
    priority = {"pass": 0, "skip": 1, "fail": 2}

    def local_name(tag: object) -> str:
        if not isinstance(tag, str):
            return ""
        return tag.rsplit("}", 1)[-1].lower()

    def record(name: str | None, status: str) -> None:
        if not name:
            return
        name = name.strip()
        if not name:
            return
        old = results.get(name)
        if old is None or priority[status] > priority[old]:
            results[name] = status

    def case_name(case: ET.Element) -> str | None:
        name = case.get("name")
        if not name:
            return None
        name = name.strip()
        classname = (case.get("classname") or case.get("class") or "").strip()
        # Preserve already-qualified/custom names such as Class#method,
        # pytest node IDs, and names that already include the classname.
        if classname and not (
            "#" in name
            or "::" in name
            or name == classname
            or name.startswith(classname + ".")
        ):
            return classname + "#" + name
        return name

    def case_status(case: ET.Element) -> str:
        child_tags = {local_name(child.tag) for child in case.iter() if child is not case}
        if child_tags & {"failure", "error"}:
            return "fail"
        if child_tags & {"skipped", "skip", "disabled", "ignored", "pending"}:
            return "skip"

        raw = ""
        for key in ("status", "result", "outcome"):
            value = case.get(key)
            if value is not None:
                raw = value.strip().lower()
                break

        if raw in {"skip", "skipped", "disabled", "ignored", "pending", "notrun", "not-run"}:
            return "skip"
        if raw in {"fail", "failed", "failure", "error", "errors", "broken", "xpass"}:
            return "fail"
        if raw in {"pass", "passed", "success", "successful", "ok", "xfailed", "xfail"}:
            return "pass"
        # Standard JUnit testcases have no status attribute when they pass.
        return "pass" if not raw else "fail"

    def consume(root: ET.Element) -> int:
        count = 0
        for case in root.iter():
            if local_name(case.tag) == "testcase":
                record(case_name(case), case_status(case))
                count += 1
        return count

    text = log.lstrip("\ufeff")

    # Prefer a complete XML document. Wrapping also supports multiple adjacent
    # testsuite documents and harmless text before or after XML.
    candidates = [text]
    first_tag = text.find("<")
    if first_tag >= 0:
        cleaned = re.sub(r"<\?xml[^>]*\?>", "", text[first_tag:], flags=re.I)
        candidates.append("<root>" + cleaned + "</root>")

    for candidate in candidates:
        try:
            root = ET.fromstring(candidate)
        except (ET.ParseError, ValueError):
            continue
        if consume(root):
            return results

    # Recover every complete testcase from truncated/malformed surrounding XML.
    # Paired cases are tried first so failure/error/skipped children are retained.
    paired = re.compile(
        r"<(?:[A-Za-z_][\w.-]*:)?testcase\b[^>]*>.*?</(?:[A-Za-z_][\w.-]*:)?testcase\s*>",
        re.I | re.S,
    )
    spans: list[tuple[int, int]] = []
    for match in paired.finditer(text):
        try:
            case = ET.fromstring(match.group(0))
        except ET.ParseError:
            continue
        record(case_name(case), case_status(case))
        spans.append(match.span())

    self_closing = re.compile(
        r"<(?:[A-Za-z_][\w.-]*:)?testcase\b[^>]*/\s*>",
        re.I | re.S,
    )
    for match in self_closing.finditer(text):
        if any(start <= match.start() < end for start, end in spans):
            continue
        try:
            case = ET.fromstring(match.group(0))
        except ET.ParseError:
            continue
        record(case_name(case), case_status(case))

    return results

problem_statement:
elevate default severity of RMG068 from info to warning (queryable projection's user implemented mapping not inlinable)
**Is your feature request related to a problem? Please describe.**
When using EF Core `IQueryable` mapping projections, sometimes user-defined mapping methods can not be inlined which causes EF Core to skip generating SQL queries for query projection but instead loads all columns and all related entities and executes the projection client-side.

**Describe the solution you'd like**
When user-defined mapping methods can not be inlined into `IQueryable`-projections, a compile warning (which can be treated as error) prevents unintentional client-side evaluations.

```csharp
[Mapper]
public static partial class PersonDtoMapper
{
    private static string MapFullName(PersonDbo src)
    {
        // this renaming prevents inlining
        var source = src;
        return source.FirstName + " " + source.LastName;
    }

    // Expected a compile warning here that MapFullName could not be inlined to MapToPersonDto() expression
    [MapPropertyFromSource(nameof(UserDto.FullName), Use = nameof(MapFullName))]
    private static partial PersonDto MapToPersonDto(PersonDbo src);
    public static partial Expression<Func<PersonDbo, PersonDto>> MapToPersonDto();
}
```

**Describe alternatives you've considered**
Always inspect generated projection after any changes.

**Additional context**

