def parser(log: str) -> dict[str, str]:
    import html
    import re
    import xml.etree.ElementTree as ET

    results: dict[str, str] = {}
    priority = {"pass": 0, "skip": 1, "fail": 2}

    def add(name: str | None, status: str) -> None:
        if not name:
            return
        name = name.strip()
        if name and priority[status] >= priority.get(results.get(name, ""), -1):
            results[name] = status

    def local_name(tag: str) -> str:
        return tag.rsplit("}", 1)[-1].rsplit(":", 1)[-1].lower()

    def read_case(case: ET.Element) -> None:
        name = case.get("name") or case.get("fullname") or case.get("classname")
        tags = {local_name(node.tag) for node in case.iter() if node is not case}
        state = (case.get("status") or case.get("result") or "").strip().lower()

        if tags & {"failure", "error"} or state in {
            "fail", "failed", "failure", "error", "errored"
        }:
            status = "fail"
        elif "skipped" in tags or state in {
            "skip", "skipped", "ignored", "disabled", "notrun", "not-run",
            "inconclusive", "pending"
        }:
            status = "skip"
        else:
            status = "pass"
        add(name, status)

    # JUnit loggers may concatenate several complete XML documents.
    document_pattern = re.compile(
        r"<(?:[\w.-]+:)?testsuites\b[\s\S]*?</(?:[\w.-]+:)?testsuites\s*>",
        re.IGNORECASE,
    )
    documents = document_pattern.findall(log)

    # Also support a report whose root is a single testsuite.
    if not documents:
        documents = re.findall(
            r"<(?:[\w.-]+:)?testsuite\b[\s\S]*?</(?:[\w.-]+:)?testsuite\s*>",
            log,
            re.IGNORECASE,
        )

    for document in documents:
        document = re.sub(r"<\?xml\b[\s\S]*?\?>", "", document, flags=re.IGNORECASE)
        try:
            root = ET.fromstring(document)
        except ET.ParseError:
            continue
        for element in root.iter():
            if local_name(element.tag) == "testcase":
                read_case(element)

    # Tolerant fallback for malformed/truncated concatenated reports. It also
    # covers self-closing testcases and is harmless for already parsed cases.
    testcase_pattern = re.compile(
        r"<(?P<prefix>[\w.-]+:)?testcase\b(?P<attrs>[^<>]*?)"
        r"(?:/\s*>|>(?P<body>[\s\S]*?)</(?:[\w.-]+:)?testcase\s*>)",
        re.IGNORECASE,
    )
    attr_pattern = re.compile(
        r"([\w:.-]+)\s*=\s*(?:\"([^\"]*)\"|'([^']*)')",
        re.DOTALL,
    )

    for match in testcase_pattern.finditer(log):
        attrs = {
            key.rsplit(":", 1)[-1].lower(): html.unescape(double or single)
            for key, double, single in attr_pattern.findall(match.group("attrs"))
        }
        name = attrs.get("name") or attrs.get("fullname") or attrs.get("classname")
        body = match.group("body") or ""
        state = (attrs.get("status") or attrs.get("result") or "").strip().lower()

        if re.search(r"<(?:[\w.-]+:)?(?:failure|error)\b", body, re.IGNORECASE) or state in {
            "fail", "failed", "failure", "error", "errored"
        }:
            status = "fail"
        elif re.search(r"<(?:[\w.-]+:)?skipped\b", body, re.IGNORECASE) or state in {
            "skip", "skipped", "ignored", "disabled", "notrun", "not-run",
            "inconclusive", "pending"
        }:
            status = "skip"
        else:
            status = "pass"
        add(name, status)

    return results
